    async function switchMapProvider(next) {
      const target = next === 'google' ? 'google' : 'mapbox';
      if (target === mapProvider && map) {
        syncMapProviderControl();
        return;
      }
      if (target === 'google' && !googleAvailable()) {
        showProviderToast('Add GOOGLE_MAPS_API_KEY to enable Google Maps.');
        syncMapProviderControl();
        return;
      }
      if (target === 'mapbox') {
        const token = MAPBOX_TOKEN || localStorage.getItem('mapbox-token');
        if (!token) {
          showProviderToast('Mapbox token required.');
          syncMapProviderControl();
          return;
        }
      }
      if (isPlaying || document.body.classList.contains('watching')) {
        try { stopPlayback(); } catch (_) {}
      }
      pendingRestoreTripId = selectedId !== 'all' ? selectedId : null;
      const gen = teardownMap();
      setPreferredProvider(target);
      setSplash(10);
      document.getElementById('splash')?.classList.remove('hidden');
      try {
        if (target === 'google') await bootGoogleMap();
        else bootMapbox(MAPBOX_TOKEN || localStorage.getItem('mapbox-token'));
        if (gen !== mapBootGeneration) return;
        setPreferredProvider(target);
        syncMapProviderControl();
      } catch (err) {
        console.error(err);
        showProviderToast(err?.message || 'Could not switch map provider');
        if (target === 'google') {
          setPreferredProvider('mapbox');
          const token = MAPBOX_TOKEN || localStorage.getItem('mapbox-token');
          if (token) bootMapbox(token);
        }
        syncMapProviderControl();
      }
    }

