    // Atlas ink — one ice-white line with a cool cyan halo for every journey (hover → pure white).
    // 31 differently-colored ribbons read as a rainbow; a single luminous ink reads as a map.
    const ATLAS_INK = '#e9f6ff';
    const ATLAS_INK_HOT = '#ffffff';
    const ATLAS_INK_DIM = '#7d93a3';
    const ATLAS_GLOW = '#5ccff0';
    const ATLAS_GLOW_HOT = '#9fe8ff';

    function atlasInk(key) {
      if (key === 'overviewHover') return ATLAS_INK_HOT;
      if (key === 'overviewDim') return ATLAS_INK_DIM;
      return ATLAS_INK;
    }

    function atlasGlow(key) {
      if (key === 'overviewHover') return ATLAS_GLOW_HOT;
      if (key === 'overviewDim') return ATLAS_INK_DIM;
      return ATLAS_GLOW;
    }

    const neonGlowWidths = {
      outerW: zoomWidth([3, 7, 5, 10, 8, 13, 11, 16, 13, 19]),
      midW: zoomWidth([3, 4.2, 5, 6, 8, 8, 11, 10, 13, 12]),
      outerBlur: 3.8,
      midBlur: 1.0,
    };

    /** Luminous single-ink ribbon: crisp core, soft halo, dark casing for legibility over satellite. */
    function atlasNeonStyle(extra = {}) {
      return {
        casing: 0.62,
        halo: 0,
        outer: 0.34,
        mid: 0.6,
        coreOp: 1,
        hi: 0.16,
        coreW: zoomWidth([3, 2.8, 5, 3.6, 7, 4.6, 9, 5.8, 11, 7, 13, 8.4, 16, 10.4]),
        casingW: zoomWidth([3, 4.2, 5, 5.2, 7, 6.4, 9, 7.8, 11, 9.2, 13, 10.8, 16, 13]),
        ...neonGlowWidths,
        ...extra,
        halo: 0,
      };
    }

    function addRouteLayers(tripId, coords, color, visible, overviewOffset, overviewDash) {
      const ids = routeLayerIds(tripId);
      const vis = visible ? 'visible' : 'none';
      const feature = lineFeature(coords);
      if (!map.getSource(ids.src)) {
        map.addSource(ids.src, { type: 'geojson', lineMetrics: true, data: feature });
        // Google/Apple nav stack: dark casing → solid route color (no white ring, no blur).
        map.addLayer({
          id: ids.casing, type: 'line', source: ids.src,
          layout: { 'line-cap': 'round', 'line-join': 'round', visibility: vis },
          paint: {
            'line-color': '#0a0e14',
            'line-width': zoomWidth([3, 2.6, 5, 3.2, 7, 4.2, 9, 5.4, 11, 6.8, 13, 8.5, 16, 10.5]),
            'line-opacity': 0.9,
          },
        });
        map.addLayer({
          id: ids.halo, type: 'line', source: ids.src,
          layout: { 'line-cap': 'round', 'line-join': 'round', visibility: vis },
          paint: {
            'line-color': '#ffffff',
            'line-width': 0,
            'line-opacity': 0,
          },
        });
        map.addLayer({
          id: ids.glowOuter, type: 'line', source: ids.src,
          layout: { 'line-cap': 'round', 'line-join': 'round', visibility: vis },
          paint: {
            'line-color': color,
            'line-width': zoomWidth([3, 5, 5, 9, 8, 14]),
            'line-opacity': 0,
            'line-blur': 0,
          },
        });
        map.addLayer({
          id: ids.glowMid, type: 'line', source: ids.src,
          layout: { 'line-cap': 'round', 'line-join': 'round', visibility: vis },
          paint: {
            'line-color': color,
            'line-width': zoomWidth([3, 3.2, 5, 5.5, 8, 9]),
            'line-opacity': 0,
            'line-blur': 0,
          },
        });
        map.addLayer({
          id: ids.core, type: 'line', source: ids.src,
          layout: { 'line-cap': 'round', 'line-join': 'round', visibility: vis },
          paint: {
            'line-width': zoomWidth([3, 1.6, 5, 2.4, 7, 3.2, 9, 4.6, 11, 6, 13, 7.5, 16, 9.5]),
            'line-color': color,
            'line-opacity': 1,
          },
        });
        map.addLayer({
          id: ids.highlight, type: 'line', source: ids.src,
          layout: { 'line-cap': 'round', 'line-join': 'round', visibility: vis },
          paint: {
            'line-color': '#ffffff',
            'line-width': zoomWidth([3, 0.8, 5, 1.4, 8, 2]),
            'line-opacity': 0,
          },
        });
        routeLineLayerIds(ids).forEach(id => {
          try { map.setPaintProperty(id, 'line-emissive-strength', 0); } catch (_) {}
        });
      } else {
        map.getSource(ids.src).setData(feature);
        routeAllLayerIds(ids).forEach(id => {
          try { map.setLayoutProperty(id, 'visibility', vis); } catch (_) {}
        });
        map.setPaintProperty(ids.glowOuter, 'line-color', color);
        map.setPaintProperty(ids.glowMid, 'line-color', color);
        map.setPaintProperty(ids.core, 'line-color', color);
      }
      map._tripRouteMeta = map._tripRouteMeta || {};
      map._tripRouteMeta[tripId] = { offset: overviewOffset || 0, dash: overviewDash || null, color };
    }

    function setRouteStyle(tripId, color, mode) {
      const ids = routeLayerIds(tripId);
      if (!map.getLayer(ids.core)) return;
      const meta = (map._tripRouteMeta && map._tripRouteMeta[tripId]) || { offset: 0, dash: null };
      const isHover = hoveredTripId === tripId && selectedId === 'all';
      const neon = atlasSoftRibbon();
      const styles = neon ? {
        overview: atlasNeonStyle({ offset: meta.offset }),
        overviewHover: atlasNeonStyle({
          outer: 0.5, mid: 0.8, coreOp: 1, hi: 0.3, casing: 0.7,
          coreW: zoomWidth([3, 2.2, 5, 3.2, 7, 4.4, 9, 5.8, 11, 7, 13, 8.5, 16, 10.5]),
          casingW: zoomWidth([3, 3.2, 5, 4.4, 7, 5.8, 9, 7.4, 11, 8.8, 13, 10.5, 16, 12.5]),
          outerW: zoomWidth([3, 7, 5, 11, 8, 14, 11, 18, 13, 22]),
          midW: zoomWidth([3, 4, 5, 6.5, 8, 9, 11, 12, 13, 14]),
          outerBlur: 4.4,
          midBlur: 1.2,
          offset: meta.offset,
        }),
        overviewDim: atlasNeonStyle({
          outer: 0.1, mid: 0.2, coreOp: 0.42, hi: 0.04, casing: 0.35,
          offset: meta.offset,
        }),
        active: navRouteStyle({
          coreW: zoomWidth([3, 3.4, 5, 5.8, 8, 8.5, 14, 12.5]),
          casingW: zoomWidth([3, 5, 5, 8, 8, 11.5, 14, 16]),
          casing: 0.94,
          offset: 0, dash: null,
        }),
        playback: navRouteStyle({
          casing: 0.82, coreOp: 0.95,
          offset: 0, dash: null,
        }),
        hidden: {
          casing: 0, halo: 0, outer: 0, mid: 0, coreOp: 0, hi: 0,
          coreW: 0, casingW: 0, haloW: 0, offset: 0, dash: null,
          outerBlur: 0, midBlur: 0,
        },
      } : {
        overview: navRouteStyle({ offset: meta.offset }),
        overviewHover: navRouteStyle({
          coreW: zoomWidth([3, 2.2, 5, 3.4, 7, 4.4, 9, 5.8, 11, 7, 13, 8.5, 16, 10.5]),
          casingW: zoomWidth([3, 3.2, 5, 4.2, 7, 5.2, 9, 6.4, 11, 7.8, 13, 9.5, 16, 11.5]),
          casing: 0.94, coreOp: 1,
          offset: meta.offset,
        }),
        overviewDim: navRouteStyle({
          casing: 0.55, coreOp: 0.72,
          offset: meta.offset,
        }),
        active: navRouteStyle({
          coreW: zoomWidth([3, 3.2, 5, 5.5, 8, 8, 14, 12]),
          casingW: zoomWidth([3, 4.8, 5, 7.5, 8, 11, 14, 15.5]),
          casing: 0.94,
          offset: 0, dash: null,
        }),
        playback: navRouteStyle({
          casing: 0.82, coreOp: 0.95,
          offset: 0, dash: null,
        }),
        hidden: {
          casing: 0, halo: 0, outer: 0, mid: 0, coreOp: 0, hi: 0,
          coreW: 0, casingW: 0, haloW: 0, offset: 0, dash: null,
          outerBlur: 0, midBlur: 0,
        },
      };
      let key = mode;
      if (mode === 'overview' && hoveredTripId && isHover) key = 'overviewHover';
      const s = styles[key] || styles.hidden;
      // Atlas home draws every journey in the same ink; the trip's own color returns in focus / Watch.
      const onAtlas = selectedId === 'all' && (key === 'overview' || key === 'overviewHover' || key === 'overviewDim');
      const paintColor = onAtlas ? atlasInk(key) : color;
      const glowColor = onAtlas ? atlasGlow(key) : paintColor;
      map.setPaintProperty(ids.casing, 'line-opacity', s.casing);
      map.setPaintProperty(ids.halo, 'line-opacity', 0);
      map.setPaintProperty(ids.glowOuter, 'line-opacity', s.outer);
      map.setPaintProperty(ids.glowMid, 'line-opacity', s.mid);
      map.setPaintProperty(ids.core, 'line-opacity', s.coreOp);
      map.setPaintProperty(ids.core, 'line-width', s.coreW);
      map.setPaintProperty(ids.casing, 'line-width', s.casingW);
      map.setPaintProperty(ids.halo, 'line-width', 0);
      map.setPaintProperty(ids.core, 'line-color', paintColor);
      map.setPaintProperty(ids.highlight, 'line-opacity', s.hi);
      map.setPaintProperty(ids.glowOuter, 'line-color', glowColor);
      map.setPaintProperty(ids.glowMid, 'line-color', glowColor);
      if (s.outerW != null) map.setPaintProperty(ids.glowOuter, 'line-width', s.outerW);
      if (s.midW != null) map.setPaintProperty(ids.glowMid, 'line-width', s.midW);
      map.setPaintProperty(ids.glowOuter, 'line-blur', s.outerBlur || 0);
      map.setPaintProperty(ids.glowMid, 'line-blur', s.midBlur || 0);
      try { map.setLayoutProperty(ids.halo, 'visibility', 'none'); } catch (_) {}
      [ids.glowOuter, ids.glowMid, ids.highlight].forEach(id => {
        try {
          const on = id === ids.glowOuter ? s.outer > 0 : id === ids.glowMid ? s.mid > 0 : s.hi > 0;
          map.setLayoutProperty(id, 'visibility', on ? 'visible' : 'none');
        } catch (_) {}
      });
      try {
        const off = (key === 'active' || key === 'playback' || key === 'hidden')
          ? (s.offset || 0)
          : routeOffsetExpr(s.offset || 0);
        const emissive = (s.outer > 0 || s.mid > 0) ? 0.85 : 0;
        routeLineLayerIds(ids).forEach(id => {
          map.setPaintProperty(id, 'line-offset', off);
          map.setPaintProperty(id, 'line-emissive-strength', (id === ids.casing || id === ids.halo) ? 0 : emissive);
        });
      } catch (_) {}
      try {
        // Solid strokes — remove dash entirely (overview_dash must not leak through).
        clearRouteDash(ids);
        [ids.casing, ids.core].forEach(id => {
          try {
            map.setLayoutProperty(id, 'line-cap', 'round');
            map.setLayoutProperty(id, 'line-join', 'round');
          } catch (_) {}
        });
      } catch (_) {}
      try {
        const bloomId = `route-${tripId}-glow-bloom`;
        if (map.getLayer(bloomId)) map.setLayoutProperty(bloomId, 'visibility', 'none');
      } catch (_) {}
    }

    function ensureTrailLayers(color) {
      if (map.getSource('active-trail')) {
        map.setPaintProperty('active-trail-line', 'line-color', color);
        return;
      }
      map.addSource('active-trail', { type: 'geojson', lineMetrics: true, data: { type: 'Feature', geometry: { type: 'LineString', coordinates: [] } } });
      map.addLayer({
        id: 'active-trail-casing', type: 'line', source: 'active-trail',
        paint: {
          'line-color': '#0a0e14',
          'line-width': zoomWidth([4, 5.5, 6, 8, 9, 11, 14, 15]),
          'line-opacity': 0.92,
        },
        layout: { 'line-cap': 'round', 'line-join': 'round' },
      });
      map.addLayer({
        id: 'active-trail-line', type: 'line', source: 'active-trail',
        paint: {
          'line-color': color,
          'line-width': zoomWidth([4, 3, 6, 5, 9, 7, 14, 10.5]),
          'line-opacity': 1,
        },
        layout: { 'line-cap': 'round', 'line-join': 'round' },
      });
      ['active-trail-casing', 'active-trail-line'].forEach(id => {
        try {
          map.setPaintProperty(id, 'line-emissive-strength', 0);
          map.setPaintProperty(id, 'line-blur', 0);
          map.removePaintProperty(id, 'line-dasharray');
        } catch (_) {}
      });
      // Hide legacy blur / white-halo trail layers if present from older sessions.
      ['active-trail-shadow', 'active-trail-glow', 'active-trail-head', 'active-trail-halo'].forEach(id => {
        try { if (map.getLayer(id)) map.setLayoutProperty(id, 'visibility', 'none'); } catch (_) {}
      });
    }

    // ── Terrain (subtle — routes use Mapbox line layers on surface) ──
    function setupTerrain() {
      setSplash(50);
      if (isGoogleMap()) {
        setSplash(70);
        return;
      }
      if (!map.getSource('mapbox-dem')) {
        map.addSource('mapbox-dem', { type:'raster-dem', url:'mapbox://mapbox.mapbox-terrain-dem-v1', tileSize:512, maxzoom:14 });
      }
      map.setTerrain({ source:'mapbox-dem', exaggeration: 0.55 });
      syncAtlasTerrain();
      setSplash(70);
    }

    let mapLabelLayerIds = null;
    function refreshMapLabelLayerIds() {
      if (!map || !map.isStyleLoaded()) return [];
      mapLabelLayerIds = map.getStyle().layers
        .filter(layer => layer.type === 'symbol')
        .map(layer => layer.id);
      return mapLabelLayerIds;
    }
    function setMapLabelsVisible(visible) {
      // Always keep Mapbox place/state/road labels on — diary used to hide every
      // symbol layer for a pure-satellite look; users need normal geography.
      if (!map || !map.isStyleLoaded()) return;
      const ids = refreshMapLabelLayerIds();
      ids.forEach(id => {
        const isOurs = id.startsWith('trip-') || id.startsWith('atlas-') || id.startsWith('mmd-');
        const vis = isOurs ? (visible ? 'visible' : 'none') : 'visible';
        try { map.setLayoutProperty(id, 'visibility', vis); } catch (_) {}
      });
    }

    // ── Premium route rendering ──
    let routesBooted = false;
    function stackOverlappingRoutes() {
      // Paint larger |offset| corridors later so dashed cores stay visible on shared roads.
      if (!map || selectedId !== 'all') return;
      const ranked = TRIPS
        .filter(t => tripInEra(t))
        .slice()
        .sort((a, b) => Math.abs(a.overview_offset || 0) - Math.abs(b.overview_offset || 0));
      ranked.forEach(trip => {
        const ids = routeLayerIds(trip.id);
        routeAllLayerIds(ids).forEach(id => {
          if (!map.getLayer(id)) return;
          try { map.moveLayer(id); } catch (_) {}
        });
      });
    }
    let routeZoomRefreshTimer = null;

    function refreshOverviewRouteGeometry() {
      if (!map || selectedId !== 'all') return;
      const zoom = map.getZoom();
      TRIPS.forEach(trip => {
        const ids = routeLayerIds(trip.id);
        const src = map.getSource(ids.src);
        if (!src) return;
        if (!tripInEra(trip)) return;
        const coords = routeDisplayCoords(trip, zoom, false);
        src.setData(lineFeature(coords));
      });
    }

    function scheduleRouteGeometryRefresh() {
      if (!map || selectedId !== 'all' || isPlaying) return;
      clearTimeout(routeZoomRefreshTimer);
      routeZoomRefreshTimer = setTimeout(() => {
        const bucket = routeZoomBucket(map.getZoom());
        if (bucket === map._routeZoomBucket) return;
        map._routeZoomBucket = bucket;
        refreshOverviewRouteGeometry();
      }, 120);
    }

    function drawRoutes() {
      const zoom = map?.getZoom() ?? 4;
      if (map) map._routeZoomBucket = routeZoomBucket(zoom);
      TRIPS.forEach(trip => {
        const isSelected = selectedId === trip.id;
        const isOverview = selectedId === 'all';
        const coords = routeDisplayCoords(trip, zoom, isSelected);
        const visible = isOverview || isSelected;
        const ids = routeLayerIds(trip.id);
        if (!routesBooted || !map.getSource(ids.src)) {
          addRouteLayers(trip.id, coords, trip.color, visible, trip.overview_offset, trip.overview_dash);
        } else {
          map.getSource(ids.src).setData(lineFeature(coords));
          const vis = visible ? 'visible' : 'none';
          routeAllLayerIds(ids).forEach(id => {
            try { map.setLayoutProperty(id, 'visibility', vis); } catch (_) {}
          });
        }
        if (!visible) setRouteStyle(trip.id, trip.color, 'hidden');
        else if (isSelected) setRouteStyle(trip.id, trip.color, 'active');
        else if (!tripInEra(trip)) setRouteStyle(trip.id, trip.color, 'hidden');
        else {
          const focus = atlasRibbonFocusIds();
          if (focus && !focus.has(trip.id)) setRouteStyle(trip.id, trip.color, 'overviewDim');
          else setRouteStyle(trip.id, trip.color, 'overview');
        }
      });
      routesBooted = true;
      stackOverlappingRoutes();
    }



    function tripInEra(trip) {
      if (yearFilter === 'all' || yearFilter == null) return true;
      const y = String(trip.start || '').slice(0, 4);
      return y === String(yearFilter);
    }

    function applyEraFilter() {
      if (eraApplying) return;
      eraApplying = true;
      try {
        document.querySelectorAll('.era-chip').forEach(el => {
          el.classList.toggle('active', el.dataset.year === String(yearFilter));
        });
        document.querySelectorAll('.trip-item').forEach(el => {
          if (el.dataset.id === 'all') { el.classList.remove('era-hidden', 'era-dim'); return; }
          const trip = TRIPS.find(t => t.id === el.dataset.id);
          const hidden = !!(trip && !tripInEra(trip));
          el.classList.toggle('era-hidden', hidden);
          el.classList.remove('era-dim');
        });
        document.querySelectorAll('.tl-seg').forEach(el => {
          const y = el.dataset.year || '';
          const hidden = yearFilter !== 'all' && y !== String(yearFilter);
          el.classList.toggle('era-hidden', hidden);
          el.classList.remove('era-dim');
        });
        if (selectedId === 'all' && map) {
          TRIPS.forEach(t => {
            if (!map.getLayer(`route-core-${t.id}`)) return;
            if (!tripInEra(t)) setRouteStyle(t.id, t.color, 'hidden');
            else setRouteStyle(t.id, t.color, 'overview');
          });
          drawAtlasSpokes();
        }
        if (typeof renderMobileDestRail === 'function') renderMobileDestRail();
      } finally {
        eraApplying = false;
      }
    }

    function setYearFilter(year) {
      yearFilter = year === 'all' ? 'all' : String(year);
      applyEraFilter();
    }

    
    function clearDestMarkers() {
      destMarkers.forEach(m => m.remove());
      destMarkers = [];
    }

    function drawDestinationConstellation() {
      clearDestMarkers();
    }

    function drawAtlasMarkers() {
      drawAtlasSpokes();
    }

    function shortTripLabel(trip) {
      if (trip.story_dest) return String(trip.story_dest).slice(0, 36);
      const raw = (trip.name || '').split('—').pop()?.trim() || trip.name || '';
      return raw.replace(/\s*·.*$/, '').slice(0, 42);
    }

    function isJourneyBrowserOpen() {
      const el = document.getElementById('journey-browser');
      return !!(el && !el.hidden && el.classList.contains('open'));
    }

    function isPanelCollapsed() {
      return !isJourneyBrowserOpen();
    }

    function isMobileLayout() {
      return (window.innerWidth || 0) <= 640;
    }

    function measureMobileChrome() {
      const root = document.documentElement;
      const journeyDock = document.getElementById('journey-dock');
      if (journeyDock) {
        const h = Math.ceil(journeyDock.getBoundingClientRect().height);
        if (h > 0) root.style.setProperty('--journey-dock-h', h + 'px');
      }
      if (!isMobileLayout()) {
        root.style.removeProperty('--mobile-chrome-h');
        root.style.removeProperty('--sheet-offset');
        return;
      }
      const timeline = document.querySelector('.timeline-bar');
      const dock = document.getElementById('watch-transport');
      const speed = document.getElementById('speed-rail');
      const jDock = document.getElementById('journey-dock');
      const gap = 10;
      let stack = 8;
      if (timeline) {
        const tlStyle = getComputedStyle(timeline);
        const tlVisible = parseFloat(tlStyle.opacity || '1') > 0.12 && tlStyle.pointerEvents !== 'none';
        if (tlVisible) {
          const tlH = Math.ceil(timeline.getBoundingClientRect().height);
          if (tlH > 0) root.style.setProperty('--timeline-h', tlH + 'px');
          stack += tlH + gap;
        }
      }
      if (jDock) {
        const jdStyle = getComputedStyle(jDock);
        const jdVisible = jdStyle.display !== 'none' && parseFloat(jdStyle.opacity || '1') > 0.12;
        if (jdVisible) {
          const jdH = Math.ceil(jDock.getBoundingClientRect().height);
          if (jdH > 0) {
            root.style.setProperty('--journey-dock-h', jdH + 'px');
            stack += jdH + gap;
          }
        }
      }
      if (dock) {
        const dockStyle = getComputedStyle(dock);
        const dockVisible = dockStyle.display !== 'none'
          && parseFloat(dockStyle.opacity || '1') > 0.12;
        if (dockVisible) {
          const dockH = Math.ceil(dock.getBoundingClientRect().height);
          if (dockH > 0) stack += dockH + gap;
        }
      }
      if (speed) {
        const speedStyle = getComputedStyle(speed);
        const speedVisible = speedStyle.display !== 'none' && parseFloat(speedStyle.opacity || '1') > 0.12;
        if (speedVisible) {
          const speedH = Math.ceil(speed.getBoundingClientRect().height);
          if (speedH > 0) stack += speedH + gap;
        }
      }
      root.style.setProperty('--mobile-chrome-h', Math.max(Math.ceil(stack), 160) + 'px');
    }

    function scheduleMobileChromeMeasure() {
      requestAnimationFrame(() => requestAnimationFrame(measureMobileChrome));
    }

    function syncJourneyChrome() {
      scheduleMobileChromeMeasure();
      if (typeof renderBrowserDestRail === 'function') renderBrowserDestRail();
      if (typeof renderJourneyDock === 'function') renderJourneyDock();
    }

    function syncMobileChrome() {
      syncJourneyChrome();
    }

    function setJourneyBrowserOpen(open) {
      const browser = document.getElementById('journey-browser');
      if (!browser) return;
      if (open) {
        // Browsing journeys always shows the full list — never a stale year/dest filter
        // left over from the last trip focus or atlas era chip.
        setYearFilter('all');
        if (typeof clearDestBrowse === 'function') clearDestBrowse();
        browser.hidden = false;
        requestAnimationFrame(() => browser.classList.add('open'));
        document.body.classList.add('journey-browser-open');
        renderBrowserDestRail();
      } else {
        browser.classList.remove('open');
        document.body.classList.remove('journey-browser-open');
        window.setTimeout(() => {
          if (!browser.classList.contains('open')) browser.hidden = true;
        }, 360);
      }
      syncJourneyChrome();
      if (map) fitTrip(true);
    }

    function setSheetState(state) {
      if (state) setJourneyBrowserOpen(true);
    }

    function ensureMobileBrowseSheet() {
      syncJourneyChrome();
    }

    function mobileSheetInset() {
      if (!isJourneyBrowserOpen()) return 0;
      const panel = document.querySelector('.journey-browser-panel');
      return panel ? Math.ceil(panel.getBoundingClientRect().height + 10) : 0;
    }

    function setPanelCollapsed(collapsed) {
      setJourneyBrowserOpen(!collapsed);
    }

    function mapCameraPadding() {
      const w = map?.getContainer()?.clientWidth || window.innerWidth || 1200;
      const h = map?.getContainer()?.clientHeight || window.innerHeight || 800;
      const mobile = w <= 640;
      const watching = document.body.classList.contains('watching');
      const browserOpen = isJourneyBrowserOpen();
      let bottomNeed;
      if (watching) {
        bottomNeed = Math.min(mobile ? 100 : 120, Math.floor(h * (mobile ? 0.14 : 0.16)));
      } else if (browserOpen && mobile) {
        bottomNeed = Math.min(mobileSheetInset() + 96, Math.floor(h * 0.62));
      } else if (mobile) {
        bottomNeed = Math.min(200, Math.floor(h * 0.26));
      } else {
        bottomNeed = Math.min(240, Math.floor(h * 0.32));
      }
      const topNeed = Math.min(mobile ? 64 : 88, Math.floor(h * (mobile ? 0.08 : 0.1)));
      const topExtra = (!mobile && selectedId !== 'all') ? Math.min(120, Math.floor(h * 0.14)) : 0;
      return {
        top: topNeed + topExtra,
        bottom: bottomNeed,
        left: mobile ? 16 : 48,
        right: Math.min(mobile ? 16 : 48, Math.floor(w * (mobile ? 0.04 : 0.06))),
      };
    }

    function setWatching(on) {
      if (isRecording) return;
      document.body.classList.toggle('watching', !!on);
      syncAtlasMood();
      const hud = document.getElementById('watch-hud');
      const transport = document.getElementById('watch-transport');
      if (hud) hud.setAttribute('aria-hidden', on ? 'false' : 'true');
      if (transport) transport.setAttribute('aria-hidden', on ? 'false' : 'true');
      if (on) {
        setWatchControlsVisible(true);
        syncWatchHud();
        // Google 3D: label-free satellite film during Watch (scene persists — never re-created).
        if (map && typeof map.setWatchMode === 'function') {
          try { map.setWatchMode(true); } catch (_) {}
        }
      } else {
        if (map && typeof map.setWatchMode === 'function') {
          try { map.setWatchMode(false); } catch (_) {}
        }
        hideRailFilmstrip();
        hideMemoryPop3d();
        document.body.classList.remove('watch-paused');
        if (watchControlsHideTimer) { clearTimeout(watchControlsHideTimer); watchControlsHideTimer = null; }
        document.getElementById('watch-hud-extras')?.setAttribute('aria-hidden', 'true');
        if (!journeyCompleteHeld) {
          document.body.classList.remove('journey-done');
          document.getElementById('cinema-title')?.classList.remove('visible');
          const actions = document.getElementById('cinema-actions');
          if (actions) actions.hidden = true;
          setWatchControlsVisible(false);
          const watchTime = document.getElementById('watch-trip-time');
          const watchStory = document.getElementById('watch-story-line');
          const watchBar = document.getElementById('watch-status-bar');
          if (watchTime) watchTime.textContent = '';
          if (watchStory) watchStory.textContent = '';
          if (watchBar) watchBar.hidden = true;
        } else {
          setWatchControlsVisible(false);
        }
      }
    }

    function syncWatchHud() {
      const trip = activeTrip();
      const meta = document.getElementById('watch-meta-pill');
      const place = document.getElementById('watch-place-label');
      if (!trip) {
        if (meta) meta.textContent = 'Select a journey';
        if (place) place.textContent = 'Atlas';
        return;
      }
      const month = (trip.start || '').slice(0, 7);
      let when = trip.name?.split('—')[0]?.trim() || month;
      const dest = trip.story_dest || trip.dest_label || shortTripLabel(trip);
      const origin = (trip.name || '').includes('→')
        ? (trip.name.split('→')[0].split('—').pop() || '').trim()
        : (trip.stops?.[0]?.location || '').split(',')[0];
      const miles = trip.miles != null ? `${Number(trip.miles).toLocaleString()} mi` : '';
      const days = trip.duration_days ? `${trip.duration_days} days` : '';
      const bits = [when, origin && dest ? `${origin} → ${dest}` : dest, miles, days].filter(Boolean);
      if (meta) meta.textContent = bits.join(' · ');
      if (place) place.textContent = dest || 'Journey';
      syncSpeedLabel();
    }

    function setWatchControlsVisible(on) {
      document.body.classList.toggle('watch-controls-visible', !!on);
    }

    function toggleWatchControls() {
      if (!document.body.classList.contains('watching') || isRecording) return;
      // Paused: keep transport + speed visible so play/pause always responds on first tap.
      if (!isPlaying) {
        setWatchControlsVisible(true);
        return;
      }
      setWatchControlsVisible(!document.body.classList.contains('watch-controls-visible'));
    }

    function mobileAutoPlayTrip() {
      if (!isMobileLayout() || selectedId === 'all') return;
      setJourneyBrowserOpen(false);
      syncJourneyChrome();
      setWatchControlsVisible(true);
      window.clearTimeout(mobileAutoPlayTrip._t);
      mobileAutoPlayTrip._t = window.setTimeout(() => {
        if (selectedId !== 'all' && !isPlaying) startPlayback(false);
      }, 480);
    }

    function showWatchTitleCard(trip, phase, state) {
      const title = document.getElementById('cinema-title');
      if (!title || isRecording) return;
      if (phase === 'intro') {
        document.body.classList.remove('journey-done');
        document.getElementById('cinema-title-text').textContent = trip?.name || state?.label || '';
        fillCinemaStats(trip, state);
        document.getElementById('cinema-subtitle').textContent = state?.caption
          || (trip ? tripPathStats(trip, state).line : '');
        const hlEl = document.getElementById('cinema-highlights');
        hlEl.innerHTML = (state?.highlights || trip?.story?.highlights || []).slice(0, 4)
          .map(h => `<span>${h}</span>`).join('');
        title.classList.add('visible');
      } else if (phase === 'outro') {
        document.body.classList.add('journey-done');
        document.getElementById('cinema-title-text').textContent = 'Journey Complete';
        fillCinemaStats(trip, state);
        document.getElementById('cinema-subtitle').textContent = '';
        document.getElementById('cinema-highlights').innerHTML = '';
        title.classList.add('visible');
      } else {
        document.body.classList.remove('journey-done');
        title.classList.remove('visible');
        fillCinemaStats(null);
      }
    }

    function drawRouteLabels() {
      routeLabelMarkers.forEach(m => m.remove());
      routeLabelMarkers = [];
    }

    function setHoveredTrip(id) {
      if (hoveredTripId === id) return;
      hoveredTripId = id;
      document.querySelectorAll('.trip-item').forEach(el => {
        el.classList.toggle('preview', !!id && el.dataset.id === id);
      });
      if (selectedId !== 'all') return;
      if (id) {
        const trip = TRIPS.find(t => t.id === id);
        if (trip) showMemoryHighlight(trip);
      }
      if (hoverRaf) cancelAnimationFrame(hoverRaf);
      hoverRaf = requestAnimationFrame(() => {
        hoverRaf = null;
        TRIPS.forEach(t => {
          if (!tripInEra(t)) setRouteStyle(t.id, t.color, 'hidden');
          else if (t.id === hoveredTripId) setRouteStyle(t.id, t.color, 'overviewHover');
          else setRouteStyle(t.id, t.color, 'overview');
        });
        drawAtlasSpokes();
      });
    }

    function isSameHomeTrip(trip) {
      if (!trip?.stops?.length) return false;
      const start = trip.stops[0];
      const end = trip.stops[trip.stops.length - 1];
      return trip.stops.length > 1
        && Math.abs(start.lat - end.lat) < 0.02
        && Math.abs(start.lng - end.lng) < 0.02;
    }

    /** Pixel offsets so round-trip home start/return stay readable at any zoom. */
    function milestoneMarkerOffset(sameHome, isStart, isEnd, geoSepDeg) {
      if (!sameHome) return [0, 0];
      // When outbound/inbound share a corridor, lean on larger pixel separation.
      const tight = geoSepDeg != null && geoSepDeg < 0.035;
      if (isStart) return tight ? [-72, -46] : [-30, -36];
      if (isEnd) return tight ? [72, 42] : [30, 32];
      return [0, 0];
    }

    /** Walk the driving path until far enough from home (and the other endpoint). */
    function endpointLngLat(trip, isStart, isEnd, otherLngLat) {
      const stop = isStart ? trip.stops[0] : trip.stops[trip.stops.length - 1];
      const path = trip.route_path || [];
      if (!isSameHomeTrip(trip) || path.length < 6) return [stop.lng, stop.lat];
      const minFromHome = 0.04; // ~4.5km
      const minFromOther = 0.035;
      const farEnough = (lng, lat) => {
        if (Math.hypot(lng - stop.lng, lat - stop.lat) < minFromHome) return false;
        if (otherLngLat && Math.hypot(lng - otherLngLat[0], lat - otherLngLat[1]) < minFromOther) return false;
        return true;
      };
      if (isStart) {
        for (let i = 1; i < path.length; i++) {
          const lat = path[i][0], lng = path[i][1];
          if (farEnough(lng, lat)) return [lng, lat];
        }
      } else if (isEnd) {
        for (let i = path.length - 2; i >= 0; i--) {
          const lat = path[i][0], lng = path[i][1];
          if (farEnough(lng, lat)) return [lng, lat];
        }
      }
      return [stop.lng, stop.lat];
    }

    function cityOnly(location) {
      return (location || '').split(',')[0].trim() || shortLabel(location);
    }

    function setMilestoneLabel(el, role, location) {
      if (!el) return;
      el.innerHTML = `<span class="role">${role}</span><span class="place">${cityOnly(location)}</span>`;
    }

    // ── Beacon markers ──
    function applyIdleStopVisuals() {
      if (!isSingleTrip() || isPlaying) return;
      const stops = activeStops();
      const lastIdx = stops.length - 1;
      stopMarkers.forEach(m => {
        const isStart = m._idx === 0;
        const isEnd = m._idx === lastIdx;
        // Show the whole journey at rest — not only the stacked home pin.
        m._vis = true; m._act = false; m._lblOn = isStart || isEnd;
        m._el.classList.toggle('visible', true);
        m._el.classList.remove('active');
        if (m._lbl) {
          m._lbl.classList.toggle('visible', isStart || isEnd);
          m._lbl.classList.remove('active');
        }
      });
    }

    function clearHubMarkers() {
      hubMarkers.forEach(m => m.remove());
      hubMarkers = [];
    }

    function drawHomeHubs() {
      clearHubMarkers();
    }

    function drawStops() {
      stopMarkers.forEach(m => m.remove()); stopMarkers = [];
      clearPhotoPins();
      clearOvernightMarkers();
      clearHubMarkers();
      clearDestMarkers();
      hideMemoryOnMap();
      const single = isSingleTrip();
      if (!single) {
        drawAtlasMarkers();
        // Welcome: polaroids on map. Atlas home: bottom film rail (paths stay clear).
        syncAtlasTiles();
        return;
      }
      clearWelcomeTiles();
      // Trip focus: path + chronological photo tiles in the bottom rail.
      renderAtlasFilmRail();
      // Trip focus: show every photo location on the map (light pins, no dark blobs).
      drawPhotoPins();
      // Night stops (tent / car sleep / hotel) sit on the path before playback starts.
      drawOvernightMarkers();
    }

    let photoMarkers = [];
    let overnightMarkers = [];
    const OVERNIGHT_STAY_KINDS = new Set(['camp', 'hotel', 'airbnb', 'car_sleep', 'friend', 'island', 'home']);
    let memoryMapMarker = null;
    let memoryStageSrc = '';

    function clearPhotoPins() {
      photoMarkers.forEach(m => {
        try { m.remove(); } catch (_) {}
      });
      photoMarkers = [];
      if (map && typeof map.clearPillars3d === 'function') {
        try { map.clearPillars3d(); } catch (_) {}
      }
      // Belt-and-suspenders: drop any orphaned Mapbox photo-pin DOM from a prior trip.
      document.querySelectorAll('.photo-pin').forEach(el => {
        try { el.remove(); } catch (_) {}
      });
      hidePhotoHover();
    }

    function clearOvernightMarkers() {
      overnightMarkers.forEach(m => {
        try { m.remove(); } catch (_) {}
      });
      overnightMarkers = [];
      document.querySelectorAll('.overnight-pin').forEach(el => {
        try { el.remove(); } catch (_) {}
      });
    }

    function overnightStopsForTrip(trip) {
      if (!trip) return [];
      const fromStops = (trip.stops || []).filter(s => {
        if (s?.lat == null || s?.lng == null) return false;
        const kind = String(s.stay_kind || '').toLowerCase();
        if (!OVERNIGHT_STAY_KINDS.has(kind)) return false;
        return !!s.overnight;
      });
      if (fromStops.length) return fromStops;
      // Fallback when playback segments carry overnight dwells but stops were trimmed.
      const seen = new Set();
      const fromPlayback = [];
      (trip.playback?.segments || []).forEach(seg => {
        if (seg.type !== 'dwell' || seg.is_photo || !seg.overnight) return;
        const kind = String(seg.stay_kind || '').toLowerCase();
        if (!OVERNIGHT_STAY_KINDS.has(kind)) return;
        const lat = Number(seg.lat);
        const lng = Number(seg.lng);
        if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
        const key = `${kind}|${lat.toFixed(5)}|${lng.toFixed(5)}`;
        if (seen.has(key)) return;
        seen.add(key);
        fromPlayback.push({
          lat,
          lng,
          stay_kind: kind,
          overnight: true,
          caption: seg.caption || seg.label || '',
          subcaption: seg.subcaption || '',
          location: seg.label || seg.caption || '',
        });
      });
      return fromPlayback;
    }

    function snapStopToRoute(stop, trip) {
      const lat = Number(stop?.lat);
      const lng = Number(stop?.lng);
      if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
      const path = trip?.route_path;
      if (!path || path.length < 2) return { lat, lng };
      const snap = nearestPointOnPath(lat, lng, path);
      return { lat: snap.lat, lng: snap.lng };
    }

    function drawOvernightMarkers() {
      clearOvernightMarkers();
      if (!isSingleTrip() || isPlaying || !map) return;
      const trip = activeTrip();
      const stops = overnightStopsForTrip(trip);
      if (!stops.length) return;
      stops.forEach(stop => {
        const pos = snapStopToRoute(stop, trip);
        if (!pos) return;
        const kind = String(stop.stay_kind || 'camp').toLowerCase();
        const el = document.createElement('div');
        el.className = 'overnight-pin';
        el.dataset.stayKind = kind;
        el.innerHTML = stayHtml(kind);
        const caption = stop.caption || stop.location || '';
        if (caption) el.title = caption;
        el.addEventListener('click', (ev) => {
          ev.stopPropagation();
          if (!map) return;
          map.easeTo({
            center: [pos.lng, pos.lat],
            zoom: Math.max(map.getZoom(), 12.5),
            pitch: 45,
            duration: 650,
            essential: true,
          });
        });
        const m = createMapMarker({ element: el, anchor: 'center', offset: [0, 0] })
          .setLngLat([pos.lng, pos.lat])
          .addTo(map);
        overnightMarkers.push(m);
      });
    }

    function photoThumbUrl(thumb) {
      if (!thumb) return '';
      if (thumb.startsWith('http') || thumb.startsWith('data:')) return thumb;
      return thumb.replace(/^\//, '');
    }

    /**
     * Hover/pins always use `thumb` (≤1280px, published to Pages).
     * Memory/lightbox may use `thumb_full` only when the build kept those
     * paths — Pages strips them because thumbs_full/ is not deployed.
     */
    function photoDisplayUrl(photo, detail) {
      if (!photo) return '';
      const hover = photoThumbUrl(photo.thumb);
      if (detail && photo.thumb_full && (typeof PHOTO_FULL_ENABLED === 'undefined' || PHOTO_FULL_ENABLED)) {
        return photoThumbUrl(photo.thumb_full) || hover;
      }
      return hover;
    }

    function showPhotoHover(photo, x, y) {
      const card = document.getElementById('photo-hover');
      if (!card || !photo?.thumb) return;
      const img = document.getElementById('photo-hover-img');
      img.src = photoDisplayUrl(photo, false);
      document.getElementById('photo-hover-title').textContent =
        (photo.album ? photo.album : 'Memory');
      const when = photo.datetime
        ? (typeof formatLocalClock === 'function'
          ? formatLocalClock(new Date(photo.datetime), photo.lng, 'medium')
          : new Date(photo.datetime).toLocaleString('en-US', { dateStyle: 'medium', timeStyle: 'short' }))
        : '';
      document.getElementById('photo-hover-meta').textContent = when;
      card.style.left = Math.min(window.innerWidth - 180, Math.max(8, x + 16)) + 'px';
      card.style.top = Math.min(window.innerHeight - 180, Math.max(8, y - 40)) + 'px';
      card.classList.add('visible');
    }

    function hidePhotoHover() {
      document.getElementById('photo-hover')?.classList.remove('visible');
    }

    function hideMemoryOnMap() {
      if (memoryMapMarker) {
        memoryMapMarker.remove();
        memoryMapMarker = null;
      }
      document.getElementById('memory-card')?.classList.remove('visible');
    }

    let memoryUserDismissed = false;
    let memoryManualOpen = false;
    let memoryDismissKey = '';

    function memoryStateKey(state) {
      return [
        state?.photo_id || '',
        state?.thumb || '',
        state?.datetime || state?.seg?.datetime || '',
      ].join('|');
    }

    function syncMemoryChrome() {
      const stage = document.getElementById('memory-stage');
      const backdrop = document.getElementById('memory-backdrop');
      const open = !!(stage && stage.classList.contains('visible'));
      const interactive = open && (!isPlaying || memoryManualOpen);
      document.body.classList.toggle('memory-paused', interactive);
      if (backdrop) {
        backdrop.hidden = !interactive;
        backdrop.classList.toggle('visible', interactive);
        backdrop.setAttribute('aria-hidden', interactive ? 'false' : 'true');
      }
    }

    function dismissMemoryStage() {
      memoryUserDismissed = true;
      memoryManualOpen = false;
      hideMemoryStage();
    }

    function hideMemoryStage() {
      const stage = document.getElementById('memory-stage');
      if (stage) {
        stage.classList.remove('visible');
        stage.setAttribute('aria-hidden', 'true');
      }
      const img = document.getElementById('memory-stage-img');
      if (img) {
        img.onload = null;
        img.onerror = null;
        // Clear pixels so the next trip never flashes the previous memory.
        img.removeAttribute('src');
        img.alt = '';
        delete img.dataset.triedHover;
      }
      memoryStageSrc = '';
      hideMemoryPop3d();
      document.body.classList.remove('memory-up');
      hideMemoryOnMap();
      syncMemoryChrome();
    }

    function prettyAlbum(name) {
      const s = String(name || '').trim();
      if (!s || /\.(heic|jpe?g|png|mov|mp4)$/i.test(s)) return 'Memory';
      return s.charAt(0).toUpperCase() + s.slice(1);
    }

    function showMemoryStage(state, opts) {
      const options = opts || {};
      const stage = document.getElementById('memory-stage');
      if (!stage || !state?.thumb) {
        hideMemoryStage();
        return;
      }
      const key = memoryStateKey(state);
      // Keep a paused/manual dismiss sticky for the same photo until play resumes
      // or the timeline moves to another memory.
      if (memoryUserDismissed && !options.force && !isPlaying && key === memoryDismissKey) {
        return;
      }
      if (options.manual) {
        memoryManualOpen = true;
        memoryUserDismissed = false;
      } else if (isPlaying) {
        memoryManualOpen = false;
        memoryUserDismissed = false;
      }
      memoryDismissKey = key;

      // Prefer full when local build kept thumb_full; Pages uses hover thumbs only.
      const hover = photoThumbUrl(state.thumb);
      const src = photoDisplayUrl(state, true) || hover;
      if (!src) {
        hideMemoryStage();
        return;
      }
      const title = prettyAlbum(state.album || '');
      const lng = state.photo_lng != null ? state.photo_lng
        : (state.lng != null ? state.lng : state.seg?.photo_lng);
      const raw = state.datetime || state.seg?.datetime || state.seg?.clock_start || '';
      const when = raw
        ? (typeof formatLocalClock === 'function'
          ? formatLocalClock(new Date(raw), lng, 'medium')
          : new Date(raw).toLocaleString('en-US', { dateStyle: 'medium', timeStyle: 'short' }))
        : '';
      const cached = (typeof thumbCache !== 'undefined') ? thumbCache.get(src) : null;
      const resolvedSrc = (cached && cached.complete && cached.naturalWidth) ? cached.src : src;
      // Photorealistic Watch: the photo rises from its light pillar on the terrain
      // (Memory Pop) while the camera orbits — the full-screen stage is for pause / manual.
      const popLat = state.photo_lat != null ? state.photo_lat : state.lat;
      const popLng = state.photo_lng != null ? state.photo_lng : state.lng;
      if (is3DScene() && isPlaying && !options.manual && !isRecording && popLat != null) {
        if (showMemoryPop3d({ src: resolvedSrc, title, when, lat: popLat, lng: popLng })) {
          stage.classList.remove('visible');
          stage.setAttribute('aria-hidden', 'true');
          memoryStageSrc = '';
          document.body.classList.add('memory-up');
          hideMemoryOnMap();
          syncMemoryChrome();
          return;
        }
      }
      hideMemoryPop3d();
      const img = document.getElementById('memory-stage-img');
      if (img) {
        const needsSwap = memoryStageSrc !== src || !img.getAttribute('src');
        if (needsSwap) {
          memoryStageSrc = src;
          delete img.dataset.triedHover;
          img.style.opacity = '0';
          img.onload = () => { img.style.opacity = '1'; };
          img.onerror = () => {
            if (hover && img.dataset.triedHover !== '1') {
              img.dataset.triedHover = '1';
              memoryStageSrc = hover;
              img.src = hover;
              return;
            }
            // Broken asset — close instead of leaving a black card over the map.
            dismissMemoryStage();
          };
          // Drop any prior frame before assigning the new trip's photo.
          img.removeAttribute('src');
          img.src = resolvedSrc;
          if (img.complete && img.naturalWidth) img.style.opacity = '1';
        }
        img.alt = title;
      }
      const titleEl = document.getElementById('memory-stage-title');
      const metaEl = document.getElementById('memory-stage-meta');
      if (titleEl) titleEl.textContent = title;
      if (metaEl) metaEl.textContent = when;
      stage.classList.add('visible');
      stage.setAttribute('aria-hidden', 'false');
      document.body.classList.add('memory-up');
      hideMemoryOnMap();
      syncMemoryChrome();
    }

    // Legacy names used by older call sites / export helpers
    function showMemoryOnMap(state) { showMemoryStage(state, { manual: true, force: true }); }
    function hideMemoryCard() { hideMemoryStage(); }
    function showMemoryCard(state) { showMemoryStage(state, { manual: true, force: true }); }

    (function wireMemoryDismiss() {
      const closeBtn = document.getElementById('memory-stage-close');
      const backdrop = document.getElementById('memory-backdrop');
      closeBtn?.addEventListener('click', (ev) => {
        ev.preventDefault();
        ev.stopPropagation();
        dismissMemoryStage();
      });
      backdrop?.addEventListener('click', (ev) => {
        ev.preventDefault();
        dismissMemoryStage();
      });
    })();

    function clusterPhotosForPins(photos, radiusKm) {
      const items = (photos || []).filter(p => p?.lat != null && p?.lng != null && p.thumb);
      const used = new Set();
      const groups = [];
      for (let i = 0; i < items.length; i++) {
        if (used.has(i)) continue;
        const seed = items[i];
        const group = [seed];
        used.add(i);
        for (let j = i + 1; j < items.length; j++) {
          if (used.has(j)) continue;
          if (haversineKm(seed.lat, seed.lng, items[j].lat, items[j].lng) <= radiusKm) {
            group.push(items[j]);
            used.add(j);
          }
        }
        groups.push(group);
      }
      return groups;
    }

    function drawPhotoPins() {
      clearPhotoPins();
      if (!isSingleTrip()) return;
      const trip = activeTrip();
      const photos = trip?.photos || [];
      // Larger clusters at trip overview so beads don't carpet the neon path.
      const clusters = clusterPhotosForPins(photos, 8);
      const pillars = [];
      clusters.forEach(group => {
        const photo = group[0];
        const snapped = snapPhotoToRoute(photo, trip);
        if (!snapped) return;
        const lat = snapped.lat;
        const lng = snapped.lng;
        if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
        pillars.push({ lat, lng, color: trip.color || '#fbbf24' });
        const el = document.createElement('div');
        // Path beads: tiny dots keep the route readable; expand to photo on hover/tap/hot.
        el.className = 'photo-pin photo-bead';
        el.dataset.photoId = photo.id || '';
        el.dataset.photoIds = group.map(p => p.id || '').filter(Boolean).join(',');
        // Inner wrapper holds scale/hover effects — Mapbox owns transform on `el`.
        const inner = document.createElement('div');
        inner.className = 'photo-pin-inner';
        const face = document.createElement('div');
        face.className = 'photo-pin-face';
        const img = document.createElement('img');
        img.alt = prettyAlbum(photo.album || 'Photo');
        img.decoding = 'async';
        img.src = photoThumbUrl(photo.thumb);
        img.addEventListener('error', () => { img.style.visibility = 'hidden'; });
        face.appendChild(img);
        inner.appendChild(face);
        if (group.length > 1) {
          const badge = document.createElement('span');
          badge.className = 'count';
          badge.textContent = String(group.length);
          inner.appendChild(badge);
        }
        el.appendChild(inner);
        el.addEventListener('mouseenter', (ev) => {
          el.classList.add('is-expanded');
          showPhotoHover(photo, ev.clientX, ev.clientY);
        });
        el.addEventListener('mousemove', (ev) => showPhotoHover(photo, ev.clientX, ev.clientY));
        el.addEventListener('mouseleave', () => {
          if (!el.classList.contains('hot')) el.classList.remove('is-expanded');
          hidePhotoHover();
        });
        el.addEventListener('click', (ev) => {
          ev.stopPropagation();
          document.querySelectorAll('.photo-pin.is-expanded').forEach(n => {
            if (n !== el && !n.classList.contains('hot')) n.classList.remove('is-expanded');
          });
          el.classList.add('is-expanded');
          if (map) {
            map.easeTo({
              center: [lng, lat],
              zoom: Math.max(map.getZoom(), 13.5),
              pitch: 45,
              duration: 700,
              essential: true,
            });
          }
          showMemoryOnMap({
            thumb: photo.thumb,
            thumb_full: photo.thumb_full || '',
            lat: photo.lat,
            lng: photo.lng,
            album: photo.album,
            datetime: photo.datetime,
            label: prettyAlbum(photo.album || 'Memory'),
            photo_id: photo.id,
          });
        });
        // Bottom anchor so the stem tip sits on the photo GPS (trip-focus + watch).
        const m = createMapMarker({ element: el, anchor: 'bottom', offset: [0, 0] })
          .setLngLat([lng, lat])
          .addTo(map);
        m._photo = photo;
        m._cluster = group;
        photoMarkers.push(m);
      });
      // Light pillars rise at every memory cluster on the photorealistic terrain.
      if (is3DScene() && typeof map.setPillars3d === 'function') {
        try { map.setPillars3d(pillars); } catch (_) {}
      }
    }

    function renderFilmstrip(photos) {
      const strip = document.getElementById('trip-filmstrip');
      if (!strip) return;
      strip.innerHTML = '';
      const list = photosInTripOrder(photos);
      list.forEach(photo => {
        if (!photo.thumb) return;
        const img = document.createElement('img');
        img.loading = 'lazy';
        img.decoding = 'async';
        img.alt = photo.album || 'Photo';
        img.title = photo.album || photo.datetime || 'Memory';
        // Assign src after alt/title so a decode failure never leaves a prior trip's bits.
        img.src = photoThumbUrl(photo.thumb);
        img.addEventListener('error', () => {
          img.remove();
        });
        img.addEventListener('click', () => {
          if (map && photo.lng != null) {
            map.easeTo({
              center: [photo.lng, photo.lat],
              zoom: Math.max(map.getZoom(), 10.5),
              pitch: 45,
              duration: 700,
              essential: true,
            });
          }
          showMemoryOnMap({
            thumb: photo.thumb,
            thumb_full: photo.thumb_full || '',
            lat: photo.lat,
            lng: photo.lng,
            album: photo.album,
            datetime: photo.datetime,
            label: photo.location || photo.album || 'Memory',
            photo_id: photo.id,
          });
        });
        strip.appendChild(img);
      });
    }



