    // ── Fit trip — frame route in continental US ──
    function fitTrip(animate=true, recap=false) {
      const bounds = createLngLatBounds();
      const trip = activeTrip();
      const photoHeavy = isSingleTrip() && (trip?.photos?.length || 0) >= 5;

      // Photo-heavy trips: frame the memories first so Colorado pins aren't lost
      // inside a continent-wide TX↔CO overview.
      if (photoHeavy && !recap) {
        trip.photos.forEach(p => {
          if (p?.lng != null && p?.lat != null) bounds.extend([p.lng, p.lat]);
        });
        if (!bounds.isEmpty()) {
          setMapLabelsVisible(true);
          map.fitBounds(bounds, {
            padding: mapCameraPadding(),
            pitch: 36,
            bearing: 0,
            duration: animate ? 1100 : 0,
            maxZoom: 9.2,
            minZoom: 5.5,
          });
          return;
        }
      }

      activeTrips().forEach(t => {
        // Prefer the driving path so round trips with identical home endpoints still frame the loop
        const path = t.route_path || [];
        if (path.length >= 2) {
          path.forEach(p => bounds.extend([p[1], p[0]]));
        } else {
          t.stops.forEach(s => bounds.extend([s.lng, s.lat]));
        }
        (t.photos || []).forEach(p => {
          if (p?.lng != null && p?.lat != null) bounds.extend([p.lng, p.lat]);
        });
      });
      if (bounds.isEmpty()) return;
      const stopCount = activeTrips().reduce((sum, t) => sum + (t.stop_count || t.stops?.length || 0), 0);
      const miles = trip?.miles || 0;
      setMapLabelsVisible(true);
      let maxZoom = 5;
      if (isSingleTrip()) {
        maxZoom = Math.min(6.2, Math.max(4.0, 7.4 - Math.log2(Math.max(stopCount, 2))));
        if (miles > 1800) maxZoom = Math.min(maxZoom, 4.4);
        else if (miles > 900) maxZoom = Math.min(maxZoom, 5.0);
        else if (miles < 450) maxZoom = Math.min(6.4, Math.max(maxZoom, 5.4));
      }
      // End-of-trip recap: north-up overview like Apple/Google route summary
      if (recap && isSingleTrip()) {
        map.fitBounds(bounds, {
          padding: { top: 72, bottom: Math.max(180, Math.floor(window.innerHeight * 0.22)), left: 56, right: 56 },
          pitch: 40,
          bearing: 0,
          duration: animate ? 2000 : 0,
          maxZoom: Math.min(maxZoom + 0.5, 6.6),
          minZoom: 3,
        });
        return;
      }
      map.fitBounds(bounds, {
        padding: mapCameraPadding(),
        pitch: isSingleTrip() ? 28 : 0,
        bearing: 0,
        duration: animate ? 1100 : 0,
        maxZoom,
        minZoom: 3,
      });
    }

