    function dwellUiCopy(state, stop) {
      const isPhoto = !!(state?.is_photo || stop?.is_photo || stop?.kind === 'photo');
      const isHome = !!(stop?.is_home_anchor || stop?.kind === 'home');
      if (isPhoto) {
        const place = prettyAlbum(state?.album || stop?.album || '');
        return {
          phase: 'Memory',
          icon: '📷',
          mode: 'memory',
          dock: `Memory · ${place}`,
          caption: `Memory · ${place}`,
        };
      }
      if (isHome) {
        return {
          phase: 'Home',
          icon: '⌂',
          mode: 'halt',
          dock: `Home · ${shortLabel(stop?.location || state?.label || '')}`,
          caption: state?.caption || `Home · ${shortLabel(stop?.location || '')}`,
        };
      }
      const stay = String(state?.stay_kind || state?.seg?.stay_kind || stop?.stay_kind || '').toLowerCase();
      const place = shortLabel(state?.label || stop?.location || '');
      if (stay === 'camp') {
        return { phase: 'Camping', icon: '⛺', mode: 'dwell', dock: `Camping · ${place}`, caption: state?.caption || `Camping · ${place}` };
      }
      if (stay === 'hotel') {
        return { phase: 'Hotel', icon: '🏨', mode: 'dwell', dock: `Hotel · ${place}`, caption: state?.caption || `Hotel · ${place}` };
      }
      if (stay === 'airbnb') {
        return { phase: 'Airbnb', icon: '🏠', mode: 'dwell', dock: `Airbnb · ${place}`, caption: state?.caption || `Airbnb · ${place}` };
      }
      if (stay === 'car_sleep') {
        return { phase: 'Car sleep', icon: '💤', mode: 'dwell', dock: `Sleeping · ${place}`, caption: state?.caption || `Slept in the car · ${place}` };
      }
      if (stay === 'friend') {
        return { phase: 'Friends', icon: '⌂', mode: 'dwell', dock: `Staying · ${place}`, caption: state?.caption || `Staying with friends · ${place}` };
      }
      if (stay === 'island') {
        return { phase: 'Island', icon: '🏝️', mode: 'dwell', dock: `Island · ${place}`, caption: state?.caption || `Island night · ${place}` };
      }
      if (stay === 'home') {
        return { phase: 'Home', icon: '⌂', mode: 'halt', dock: `Home · ${place}`, caption: state?.caption || `Home · ${place}` };
      }
      if (stay === 'halt') {
        return { phase: 'Halt', icon: '⏸', mode: 'halt', dock: `Halt · ${place}`, caption: state?.caption || `Halt · ${place}` };
      }
      if (stay === 'charge') {
        return { phase: 'Charging', icon: '⚡', mode: 'halt', dock: `Charging · ${place}`, caption: state?.caption || `Charging · ${place}` };
      }
      if (stay === 'trailhead') {
        return { phase: 'Trailhead', icon: '🥾', mode: 'halt', dock: `Trailhead · ${place}`, caption: state?.caption || `Trailhead · ${place}` };
      }
      return {
        phase: 'Charging',
        icon: '⚡',
        mode: 'halt',
        dock: `Charging · ${place}`,
        caption: state?.caption || `Charging · ${place}`,
      };
    }

