    function seekPlayback(dir) {
      if (isRecording) return;
      if (!isSingleTrip()) return;
      const pb = activePlayback();
      if (!pb?.total_video_ms) return;
      const marks = playbackLandmarkTimes(pb);
      const near = 400;
      let target = null;
      if (dir > 0) {
        target = marks.find((t) => t > animTimeMs + near);
      } else {
        for (let i = marks.length - 1; i >= 0; i--) {
          if (marks[i] < animTimeMs - near) {
            target = marks[i];
            break;
          }
        }
      }
      // No next/prev moment: jump a readable chunk (~10% of the journey).
      if (target == null) {
        const wallStep = 25000 * PLAYBACK_SPEED_REF;
        const pctStep = pb.total_video_ms * 0.1;
        const step = Math.max(wallStep, Math.min(pctStep, pb.total_video_ms * 0.18));
        target = animTimeMs + dir * step;
      }
      seekToMs(target);
    }

    /** Jump the timeline to an absolute time (Prev/Next moments, rail chapter taps). */
    function seekToMs(targetMs) {
      const pb = activePlayback();
      if (!pb?.total_video_ms) return;
      animTimeMs = Math.max(0, Math.min(pb.total_video_ms - 16, targetMs));
      lastTs = 0;
      resetNavChase();
      if (is3DScene()) {
        try { map.resetChase3d(); } catch (_) {}
      }
      const state = positionAtTime(animTimeMs);
      updateTrailFromState(state);
      if (state) applyPlaybackCamera(state, true);
      const transport = ui('watch-transport');
      if (transport) {
        transport.classList.remove('seek-flash');
        // Force reflow so repeated seeks retrigger the flash animation.
        void transport.offsetWidth;
        transport.classList.add('seek-flash');
      }
      setWatchControlsVisible(true);
      armWatchControlsAutoHide();
    }
